/**
 * The immutable Cinder token base, as data.
 *
 * A theme is a set of overrides on this base, so a consumer that evaluates or
 * saves a theme needs the base it was written against. This exports the
 * resolver and every bundled token document keyed by relative path (the same
 * keys the resolver's `$ref`s use), the package version, and a digest of the
 * sources so a saved theme can detect that the base has since changed.
 *
 * The documents are the package's own source files, imported as JSON: one copy,
 * no generated duplicate. The version and digest are generated by
 * `tokens:generate` and checked by `tokens:check`; the runtime test recomputes
 * the digest from these documents and fails if they disagree.
 */

import resolverSource from '../cinder.resolver.json' with { type: 'json' };
import motionDefault from '../modes/motion-default.tokens.json' with { type: 'json' };
import motionForcedReduced from '../modes/motion-forced-reduced.tokens.json' with { type: 'json' };
import motionReduced from '../modes/motion-reduced.tokens.json' with { type: 'json' };
import colorsSet from '../sets/colors.tokens.json' with { type: 'json' };
import componentsSet from '../sets/components.tokens.json' with { type: 'json' };
import foundationSet from '../sets/foundation.tokens.json' with { type: 'json' };
import semanticSet from '../sets/semantic.tokens.json' with { type: 'json' };
import darkTheme from '../themes/dark.tokens.json' with { type: 'json' };
import lightTheme from '../themes/light.tokens.json' with { type: 'json' };
import { BASE_SOURCE_DIGEST } from './base-corpus.generated.ts';
import { VERSION } from './package-version.generated.ts';
import type { ResolverDocument, TokenDocument } from './types.ts';
import { assertValidResolverDocument } from './validate.ts';

/** The bundled Cinder base: what a theme's overrides are applied to. */
export type CinderBase = {
  /**
   * The `@lostgradient/cinder` version these sources ship in: `workspace` in the
   * monorepo, and the published version in a mirrored package.
   */
  packageVersion: string;
  /** `sha256:<hex>` over the canonical form of `{ resolver, documents }`. */
  sourceDigest: string;
  resolver: ResolverDocument;
  /** Token documents keyed by the relative path the resolver references. */
  documents: Readonly<Record<string, TokenDocument>>;
};

function isTokenDocument(value: unknown): value is TokenDocument {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

function tokenDocument(path: string, value: unknown): TokenDocument {
  if (!isTokenDocument(value)) throw new Error(`Bundled token document ${path} is not an object.`);
  return value;
}

function bundledResolver(value: unknown): ResolverDocument {
  assertValidResolverDocument(value);
  return value;
}

const bundledDocuments: Array<[string, unknown]> = [
  ['modes/motion-default.tokens.json', motionDefault],
  ['modes/motion-forced-reduced.tokens.json', motionForcedReduced],
  ['modes/motion-reduced.tokens.json', motionReduced],
  ['sets/colors.tokens.json', colorsSet],
  ['sets/components.tokens.json', componentsSet],
  ['sets/foundation.tokens.json', foundationSet],
  ['sets/semantic.tokens.json', semanticSet],
  ['themes/dark.tokens.json', darkTheme],
  ['themes/light.tokens.json', lightTheme],
];

export const CINDER_BASE: CinderBase = {
  packageVersion: VERSION,
  sourceDigest: BASE_SOURCE_DIGEST,
  resolver: bundledResolver(resolverSource),
  documents: Object.fromEntries(
    bundledDocuments.map(([path, document]) => [path, tokenDocument(path, document)]),
  ),
};
